SELECT * FROM (SELECT p.id AS position_id, m.observed_at, m.price, m.source, m.delivery_status, ROW_NUMBER() OVER (PARTITION BY p.id ORDER BY m.observed_at DESC) AS rn FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event m ON m.symbol = p.symbol AND m.observed_at BETWEEN DATE_SUB(p.closed_at, INTERVAL 60 SECOND) AND DATE_ADD(p.closed_at, INTERVAL 1 SECOND) WHERE p.id IN (182,172,162,158,143,137)) x WHERE rn <= 3 ORDER BY position_id, observed_at LIMIT 18